import {
  GitBranch,
  Laptop,
  RefreshCw,
  Terminal as TerminalIcon,
} from "lucide-react";
import React from "react";

export type RemoteSessionItem = {
  sessionId: string;
  title?: string | null;
  workspaceId?: string | null;
  worktreeLabel?: string | null;
  running: boolean;
};

type RemoteSessionListProps = {
  sessions: RemoteSessionItem[];
  onSelect: (sessionId: string) => void;
  onRefresh: () => void;
};

export const RemoteSessionList: React.FC<RemoteSessionListProps> = ({
  sessions,
  onSelect,
  onRefresh,
}) => {
  return (
    <div className="max-w-xl mx-auto p-4 space-y-6">
      {/* Workspace Header Overview */}
      <div className="flex items-center justify-between pb-3 border-b border-[#262833]">
        <div className="flex items-center gap-2.5">
          <div className="w-8 h-8 rounded-lg bg-blue-600/10 border border-blue-500/20 flex items-center justify-center text-blue-400">
            <Laptop size={18} />
          </div>
          <div>
            <h2 className="text-sm font-semibold text-white tracking-tight">
              Desktop Workspace
            </h2>
            <p className="text-[11px] text-[#8b949e]">
              Connected to Ferryx native engine
            </p>
          </div>
        </div>
        <button
          type="button"
          onClick={onRefresh}
          className="flex items-center gap-1.5 px-2.5 py-1.5 bg-[#1a1d26] hover:bg-[#222734] active:scale-95 text-[#c9d1d9] border border-[#2c3140] rounded text-xs font-medium transition-all"
        >
          <RefreshCw size={13} />
          Refresh
        </button>
      </div>

      {/* Terminal Sessions Section */}
      <div className="space-y-3">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <TerminalIcon size={15} className="text-[#8b949e]" />
            <h3 className="text-xs font-semibold uppercase tracking-wider text-[#8b949e]">
              Active Terminals ({sessions.length})
            </h3>
          </div>
        </div>

        {sessions.length === 0 ? (
          <div className="text-center py-12 px-4 bg-[#12141a] border border-[#262833] rounded-xl space-y-3">
            <div className="w-10 h-10 mx-auto rounded-full bg-[#1c202c] flex items-center justify-center text-[#6e7681]">
              <TerminalIcon size={20} />
            </div>
            <div className="space-y-1">
              <p className="text-sm font-medium text-[#c9d1d9]">No active terminals</p>
              <p className="text-xs text-[#8b949e]">
                Open a terminal in your desktop Ferryx app to attach.
              </p>
            </div>
          </div>
        ) : (
          <div className="grid gap-2.5">
            {sessions.map((s) => (
              <div
                key={s.sessionId}
                onClick={() => onSelect(s.sessionId)}
                className="group relative flex items-center justify-between p-3.5 bg-[#12141a] border border-[#262833] hover:border-blue-500/50 hover:bg-[#161922] rounded-xl cursor-pointer transition-all active:scale-[0.99]"
              >
                <div className="flex items-start gap-3 min-w-0">
                  <div className="w-8 h-8 rounded-lg bg-[#1c202c] border border-[#2c3140] flex items-center justify-center text-[#8b949e] group-hover:text-blue-400 group-hover:border-blue-500/30 transition-colors shrink-0 mt-0.5">
                    <TerminalIcon size={16} />
                  </div>
                  <div className="min-w-0 space-y-0.5">
                    <div className="flex items-center gap-2">
                      <span className="font-mono text-xs font-semibold text-[#fafafa] truncate">
                        {s.title || `Terminal (${s.sessionId.substring(0, 8)})`}
                      </span>
                      <span className="inline-flex items-center gap-1 px-1.5 py-0.5 rounded text-[10px] font-medium bg-emerald-500/10 text-emerald-400 border border-emerald-500/20">
                        <span className="w-1.5 h-1.5 rounded-full bg-emerald-400 animate-pulse" />
                        Running
                      </span>
                    </div>
                    <div className="flex items-center gap-2 text-[11px] text-[#8b949e]">
                      <span className="flex items-center gap-1 font-mono">
                        <GitBranch size={12} />
                        {s.worktreeLabel || "main"}
                      </span>
                      <span>•</span>
                      <span className="font-mono text-[10px] text-[#6e7681]">
                        ID: {s.sessionId.substring(0, 8)}
                      </span>
                    </div>
                  </div>
                </div>

                <div className="shrink-0 pl-3">
                  <span className="inline-flex items-center justify-center px-3 py-1.5 bg-blue-600 group-hover:bg-blue-500 text-white rounded-lg text-xs font-medium shadow-sm transition-colors">
                    Attach
                  </span>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useEffect, useState } from "react";
import { PairingPage } from "./PairingPage";
import { RemoteSessionItem, RemoteSessionList } from "./RemoteSessionList";
import { RemoteTerminal } from "./RemoteTerminal";

const TOKEN_KEY = "ferryx_remote_token";
const LEGACY_TOKEN_KEY = "rorca_remote_token";

export const RemoteApp: React.FC = () => {
  const [token, setToken] = useState<string | null>(
    () => localStorage.getItem(TOKEN_KEY) ?? localStorage.getItem(LEGACY_TOKEN_KEY)
  );
  const [sessions, setSessions] = useState<RemoteSessionItem[]>([]);
  const [activeSessionId, setActiveSessionId] = useState<string | null>(null);

  useEffect(() => {
    // Check fragment #pair=<code >
    const hash = window.location.hash;
    if (hash.startsWith("#pair=")) {
      const code = hash.replace("#pair=", "");
      fetch("/api/v1/pair/exchange", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          code,
          deviceName: navigator.userAgent.includes("Mobile") ? "Mobile Device" : "Browser Device",
        }),
      })
        .then((res) => res.json())
        .then((data) => {
          if (data.token) {
            handlePaired(data.token);
            window.location.hash = "";
          }
        })
        .catch(() => {});
    }
  }, []);

  const handlePaired = (newToken: string) => {
    localStorage.setItem(TOKEN_KEY, newToken);
    localStorage.removeItem(LEGACY_TOKEN_KEY);
    setToken(newToken);
  };

  const loadSessions = async () => {
    if (!token) return;
    try {
      const res = await fetch(`/api/v1/sessions?token=${encodeURIComponent(token)}`);
      if (!res.ok) {
        localStorage.removeItem(TOKEN_KEY);
        localStorage.removeItem(LEGACY_TOKEN_KEY);
        setToken(null);
        return;
      }
      const data = await res.json();
      setSessions(data);
    } catch {
      // ignore
    }
  };

  useEffect(() => {
    if (token) {
      loadSessions();
    }
  }, [token]);

  if (!token) {
    return <PairingPage onPaired={handlePaired} />;
  }

  if (activeSessionId) {
    return (
      <RemoteTerminal
        sessionId={activeSessionId}
        token={token}
        onBack={() => {
          setActiveSessionId(null);
          loadSessions();
        }}
      />
    );
  }

  return (
    <div className="min-h-screen bg-neutral-950 text-neutral-100 flex flex-col">
      <header className="px-4 py-3 bg-neutral-900 border-b border-neutral-800 flex justify-between items-center">
        <h1 className="text-base font-bold flex items-center gap-2">
          🦀 Ferryx Remote
        </h1>
        <button
          onClick={() => {
            localStorage.removeItem(TOKEN_KEY);
            localStorage.removeItem(LEGACY_TOKEN_KEY);
            setToken(null);
          }}
          className="text-xs text-neutral-500 hover:text-neutral-300"
        >
          Disconnect
        </button>
      </header>

      <main className="flex-1 p-4">
        <RemoteSessionList
          sessions={sessions}
          onSelect={(id) => setActiveSessionId(id)}
          onRefresh={loadSessions}
        />
      </main>
    </div>
  );
};

import { cleanup, fireEvent, render, screen } from "@testing-library/react";
import { afterEach, describe, expect, it, vi } from "vitest";
import { MobileKeyDock } from "../components/MobileKeyDock";
import { PairingPage } from "./PairingPage";
import { RemoteApp } from "./RemoteApp";
import { RemoteSessionList } from "./RemoteSessionList";

afterEach(cleanup);

describe("Remote UI Components", () => {
  it("PairingPage renders 6-digit PIN input and handles submission", () => {
    const handlePaired = vi.fn();
    render(<PairingPage onPaired={handlePaired} />);

    const input = screen.getByPlaceholderText(/6-digit PIN/i);
    expect(input).toBeInTheDocument();
    expect(input).toHaveAttribute("maxLength", "6");
  });

  it("PairingPage renders Ferryx Desktop branding helper text", () => {
    const handlePaired = vi.fn();
    render(<PairingPage onPaired={handlePaired} />);

    expect(
      screen.getByText(/Enter the 6-digit PIN from your Ferryx Desktop settings/i)
    ).toBeInTheDocument();
  });

  it("RemoteSessionList displays active terminal sessions and attach buttons", () => {
    const handleSelect = vi.fn();
    const handleRefresh = vi.fn();
    const sessions = [
      {
        sessionId: "test-session-123456",
        title: "Main Shell",
        worktreeLabel: "feature/remote-test",
        running: true,
      },
    ];

    render(
      <RemoteSessionList
        sessions={sessions}
        onSelect={handleSelect}
        onRefresh={handleRefresh}
      />
    );

    expect(screen.getByText(/Main Shell/i)).toBeInTheDocument();
    expect(screen.getByText(/feature\/remote-test/i)).toBeInTheDocument();

    fireEvent.click(screen.getByText(/Attach/i));
    expect(handleSelect).toHaveBeenCalledWith("test-session-123456");
  });

  it("RemoteSessionList renders Ferryx branding in header and empty state", () => {
    const handleSelect = vi.fn();
    const handleRefresh = vi.fn();

    render(
      <RemoteSessionList
        sessions={[]}
        onSelect={handleSelect}
        onRefresh={handleRefresh}
      />
    );

    expect(screen.getByText("Connected to Ferryx native engine")).toBeInTheDocument();
    expect(
      screen.getByText(/Open a terminal in your desktop Ferryx app to attach/i)
    ).toBeInTheDocument();
  });

  it("MobileKeyDock dispatches primary key actions and latches Ctrl/Alt modifiers", () => {
    const handleSendKey = vi.fn();
    render(<MobileKeyDock onSendKey={handleSendKey} />);

    fireEvent.click(screen.getByText("Ctrl-C"));
    expect(handleSendKey).toHaveBeenCalledWith("ctrl-c");

    fireEvent.click(screen.getByText("Tab"));
    expect(handleSendKey).toHaveBeenCalledWith("tab");

    // Latch Ctrl + C
    fireEvent.click(screen.getByText("Ctrl"));
    fireEvent.click(screen.getByText("Tab"));
    expect(handleSendKey).toHaveBeenCalledWith("ctrl-tab");
  });

  it("RemoteApp renders Ferryx Remote in header and does not contain rorca", () => {
    localStorage.setItem("ferryx_remote_token", "test-token-xyz");
    render(<RemoteApp />);

    const header = screen.getByRole("banner");
    expect(header).toHaveTextContent(/Ferryx Remote/i);
    expect(header.textContent).not.toContain("rorca");
    localStorage.clear();
  });

  it("RemoteApp supports legacy rorca_remote_token with Ferryx Remote header", () => {
    localStorage.setItem("rorca_remote_token", "legacy-token-123");
    render(<RemoteApp />);

    const header = screen.getByRole("banner");
    expect(header).toHaveTextContent(/Ferryx Remote/i);
    expect(header.textContent).not.toContain("rorca");
    localStorage.clear();
  });
});

import type {
  Worktree,
  WorktreeIdentity,
} from "./types";
import type { RegisteredProject } from "./tauri";

const TOKEN_KEY = "ferryx_remote_token";

export function getRemoteAuthToken(): string | null {
  return localStorage.getItem(TOKEN_KEY);
}

export function setRemoteAuthToken(token: string) {
  localStorage.setItem(TOKEN_KEY, token);
}

export function clearRemoteAuthToken() {
  localStorage.removeItem(TOKEN_KEY);
}

export class RemoteClient {
  private baseUrl: string;
  private ws: WebSocket | null = null;
  private eventListeners: Map<string, Set<(payload: any) => void>> = new Map();
  private reconnectTimer: any = null;

  constructor(baseUrl: string = window.location.origin) {
    this.baseUrl = baseUrl.replace(/\/$/, "");
  }

  private authHeader(): Record<string, string> {
    const token = getRemoteAuthToken();
    return token ? { Authorization: `Bearer ${token}` } : {};
  }

  async fetchJson<T>(endpoint: string, options: RequestInit = {}): Promise<T> {
    const res = await fetch(`${this.baseUrl}${endpoint}`, {
      ...options,
      headers: {
        "Content-Type": "application/json",
        ...this.authHeader(),
        ...(options.headers || {}),
      },
    });
    if (!res.ok) {
      if (res.status === 401) {
        clearRemoteAuthToken();
      }
      throw new Error(`Remote API error ${res.status}: ${await res.text()}`);
    }
    return res.json();
  }

  async getWorkspaceState(): Promise<{
    projects: RegisteredProject[];
    activeWorkspaceId: string;
    worktrees: Worktree[];
    sessions: Array<{ sessionId: string; running: boolean }>;
  }> {
    return this.fetchJson("/api/v1/workspace/state");
  }

  async listWorktrees(_workspaceId: string): Promise<Worktree[]> {
    const state = await this.getWorkspaceState();
    return state.worktrees || [];
  }

  async createWorktree(request: {
    workspaceId: string;
    worktree: WorktreeIdentity;
    baseRef?: string | null;
  }): Promise<Worktree> {
    return this.fetchJson("/api/v1/workspace/worktrees", {
      method: "POST",
      body: JSON.stringify(request),
    });
  }

  async deleteWorktree(request: {
    workspaceId: string;
    worktree: WorktreeIdentity;
    deleteBranch?: boolean | null;
  }): Promise<void> {
    await this.fetchJson("/api/v1/workspace/worktrees", {
      method: "DELETE",
      body: JSON.stringify(request),
    });
  }

  async spawnTerminal(_request: {
    workspaceId: string;
    worktree?: WorktreeIdentity | null;
    cols?: number;
    rows?: number;
  }): Promise<{ sessionId: string }> {
    // In remote mode, sessions are live on desktop; we attach or spawn
    return { sessionId: `remote-${Date.now()}` };
  }

  connectEvents() {
    if (this.ws || !getRemoteAuthToken()) return;
    const protocol = window.location.protocol === "https:" ? "wss:" : "ws:";
    const token = getRemoteAuthToken();
    const wsUrl = `${protocol}//${window.location.host}/api/v1/events?token=${encodeURIComponent(token || "")}`;

    try {
      this.ws = new WebSocket(wsUrl);
      this.ws.onmessage = (ev) => {
        try {
          const msg = JSON.parse(ev.data);
          const listeners = this.eventListeners.get(msg.event);
          if (listeners) {
            for (const fn of listeners) {
              fn(msg.payload);
            }
          }
        } catch {
          // ignore
        }
      };

      this.ws.onclose = () => {
        this.ws = null;
        clearTimeout(this.reconnectTimer);
        this.reconnectTimer = setTimeout(() => this.connectEvents(), 3000);
      };
    } catch {
      // ignore
    }
  }

  listen(event: string, handler: (payload: any) => void): () => void {
    const listeners = this.eventListeners.get(event) ?? new Set();
    listeners.add(handler);
    this.eventListeners.set(event, listeners);
    this.connectEvents();

    return () => {
      listeners.delete(handler);
    };
  }
}

export const defaultRemoteClient = new RemoteClient();

