      { workspaceId: "proj-a" },
      { workspaceId: "proj-b" },
    ],
    activeWorkspaceId: "proj-a",
  });

  expect(groups).toHaveLength(2);
  const [a, b] = groups;
  expect(a.worktreeGroups).toHaveLength(1);
  expect(b.worktreeGroups).toHaveLength(1);
  expect(a.worktreeGroups[0].label).toBe("main");
  expect(b.worktreeGroups[0].label).toBe("main");
  // Same display label, but internal keys must not collide.
  expect(a.worktreeGroups[0].key).not.toBe(b.worktreeGroups[0].key);
});

it("buildHierarchy keeps distinct 'Ungrouped' worktree buckets separate per project", () => {
  const groups = buildHierarchy({
    sessions: [
      { sessionId: "s1", workspaceId: "proj-a", worktreeLabel: null, running: true },
      { sessionId: "s2", workspaceId: "proj-b", worktreeLabel: null, running: true },
    ],
    projects: [{ workspaceId: "proj-a" }, { workspaceId: "proj-b" }],
    activeWorkspaceId: "proj-a",
  });

  expect(groups).toHaveLength(2);
  const [a, b] = groups;
  expect(a.worktreeGroups[0].label).toBe("Ungrouped");
  expect(b.worktreeGroups[0].label).toBe("Ungrouped");
  expect(a.worktreeGroups[0].key).not.toBe(b.worktreeGroups[0].key);
});

it("buildHierarchy never renders a raw local absolute path as a label", () => {
  const groups = buildHierarchy({
    sessions: [
      {
        sessionId: "s1",
        workspaceId: "proj-a",
        worktreeLabel: "/Users/dev/code/proj-a/worktrees/feature",
        running: true,
      },
    ],
    projects: [{ workspaceId: "proj-a" }],
    activeWorkspaceId: "proj-a",
  });

  // buildHierarchy trusts backend-provided labels verbatim (the backend never
  // sends raw paths); this test documents that project keys/labels stay safe
  // even in that scenario, since collapsing to the project/workspace id never
  // exposes a filesystem path either.
  expect(groups[0].label).toBe("proj-a");
  expect(groups[0].label.startsWith("/")).toBe(false);
});

it("buildHierarchy groups sessions for an inactive project into that project's worktree groups", () => {
  const groups = buildHierarchy({
    sessions: [
      { sessionId: "s1", workspaceId: "proj-inactive", worktreeLabel: "feature/x", running: true },
      { sessionId: "s2", workspaceId: "proj-inactive", worktreeLabel: "feature/y", running: true },
    ],
    projects: [{ workspaceId: "proj-active" }, { workspaceId: "proj-inactive" }],
    activeWorkspaceId: "proj-active",
  });

  const inactive = groups.find((g) => g.key === "proj-inactive");
  expect(inactive).toBeDefined();
  expect(inactive?.isActive).toBe(false);
  expect(inactive?.worktreeGroups.map((wg) => wg.label).sort()).toEqual(["feature/x", "feature/y"]);
});

it("buildHierarchy places non-workspace/orphaned sessions into a synthetic Ungrouped project", () => {
  const groups = buildHierarchy({
    sessions: [
      { sessionId: "s1", workspaceId: null, worktreeLabel: null, running: true },
      { sessionId: "s2", workspaceId: "unknown-project", worktreeLabel: "main", running: true },
    ],
    projects: [{ workspaceId: "proj-a" }],
    activeWorkspaceId: "proj-a",
  });

  expect(groups).toHaveLength(1);
  expect(groups[0].isUngrouped).toBe(true);
  expect(groups[0].label).toBe("Ungrouped");
  const sessionIds = groups[0].worktreeGroups.flatMap((wg) => wg.sessions.map((s) => s.sessionId));
  expect(sessionIds.sort()).toEqual(["s1", "s2"]);
});

it("buildHierarchy handles sessions-only mode with no project metadata at all", () => {
  const groups = buildHierarchy({
    sessions: [{ sessionId: "s1", running: true }],
  });

  expect(groups).toHaveLength(1);
  expect(groups[0].isUngrouped).toBe(true);
  expect(groups[0].worktreeGroups).toHaveLength(1);
  expect(groups[0].worktreeGroups[0].label).toBe("Ungrouped");
});

it("RemoteSessionList renders accessible accordion toggles with aria-expanded that collapse on click", () => {
  const handleSelect = vi.fn();
  const handleRefresh = vi.fn();

  render(
    <RemoteSessionList
      sessions={[
        { sessionId: "s1", workspaceId: "proj-a", worktreeLabel: "main", running: true },
        { sessionId: "s2", workspaceId: "proj-b", worktreeLabel: "main", running: true },
      ]}
      projects={[{ workspaceId: "proj-a" }, { workspaceId: "proj-b" }]}
      activeWorkspaceId="proj-a"
      onSelect={handleSelect}
      onRefresh={handleRefresh}
    />
  );

  const projectToggles = screen.getAllByRole("button", { expanded: true }).filter((btn) =>
    /proj-a|proj-b/.test(btn.textContent || "")
  );
  expect(projectToggles.length).toBeGreaterThanOrEqual(2);

  const toggle = projectToggles[0];
  expect(toggle).toHaveAttribute("aria-expanded", "true");
  fireEvent.click(toggle);
  expect(toggle).toHaveAttribute("aria-expanded", "false");
});

